      "type": "string",
      "title": "Requester",
      "description": "The person or machine that requested this export"
    },
    "status": {
      "type": "string",
      "title": "Status",
      "description": "The status of this export (e.g. is it running/finished?)",
      "enum": [
        "PENDING",
        "ABORTED",
        "COMPLETED"
      ]
    },
